export function FreeQuotaRecordFromTuple(abiTuple: [bigint, bigint]) {
  return getABIStructFromABITuple(abiTuple, APP_SPEC.structs.FreeQuotaRecord, APP_SPEC.structs) as FreeQuotaRecord
}

